import Foundation

// MARK: - Fixture mode: a credential-free transport over bundled, AccessLink-shaped JSON
//
// The fixtures (Fixtures/*.json, regenerated by Scripts/make_fixtures.py) are SYNTHETIC: 14 nights ending
// on the wake day 2026-10-28 for a made-up wearer in America/Chicago, with one deliberately bad night
// (2026-10-24). They follow the documented AccessLink response shapes, so the real transport and this one
// drive the identical pipeline.

public enum PolarFixtures {
    /// Last wake day in the bundled fixtures.
    public static let lastDay = "2026-10-28"
    /// The zone the fixtures were generated in.
    public static let timeZone = TimeZone(secondsFromGMT: -5 * 3600)!

    /// `YYYY-MM-DD` of an instant in the fixtures' zone (the wake day of a session's `end`).
    public static func dayKey(_ date: Date) -> String {
        let f = DateFormatter()
        f.calendar = Calendar(identifier: .gregorian); f.timeZone = timeZone
        f.locale = Locale(identifier: "en_US_POSIX"); f.dateFormat = "yyyy-MM-dd"
        return f.string(from: date)
    }

    public static func data(_ name: String) -> Data? {
        guard let url = Bundle.module.url(forResource: name, withExtension: "json", subdirectory: "Fixtures") else { return nil }
        return try? Data(contentsOf: url)
    }

    /// Run the full pipeline over the fixtures (what the app's "Preview with sample data" and the demo CLI do).
    public static func runDemo() async throws -> PolarSyncResult {
        try await PolarSyncPipeline(transport: PolarFixtureTransport(), timeZone: timeZone)
            .run(today: lastDay, days: 14)
    }
}

/// Serves the bundled fixtures for the paths `PolarSyncPipeline` requests. Unknown paths → 404.
public struct PolarFixtureTransport: PolarAccessLinkTransport {
    public init() {}

    public func get(_ path: String, query: [String: String]) async throws -> PolarHTTPResponse {
        func ok(_ name: String) -> PolarHTTPResponse {
            PolarFixtures.data(name).map { PolarHTTPResponse(status: 200, body: $0) } ?? PolarHTTPResponse(status: 404, body: Data())
        }
        switch path {
        case "users/sleep": return ok("sleep")
        case "users/nightly-recharge": return ok("nightly-recharge")
        case "users/activities": return ok("activities")
        case "users/cardio-load": return ok("cardio-load")
        default:
            let prefix = "users/continuous-heart-rate/"
            guard path.hasPrefix(prefix), let all = PolarFixtures.data("continuous-heart-rate"),
                  let days = try? JSONSerialization.jsonObject(with: all) as? [[String: Any]] else {
                return PolarHTTPResponse(status: 404, body: Data())
            }
            let date = String(path.dropFirst(prefix.count))
            // The real per-date endpoint returns one day object, or 204/404 when there is none.
            guard let day = days.first(where: { $0["date"] as? String == date }),
                  let body = try? JSONSerialization.data(withJSONObject: day) else {
                return PolarHTTPResponse(status: 204, body: Data())
            }
            return PolarHTTPResponse(status: 200, body: body)
        }
    }
}
